# -*- coding: utf-8 -*-
"""தமிழ் ஜாதகம் calculation API (FastAPI). All numbers come from Swiss Ephemeris; nothing is generated by an LLM."""
from __future__ import annotations
import os, logging
from typing import Literal, Optional
from fastapi import FastAPI, HTTPException, Query
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field, field_validator
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError
from . import engine, places, panchang, palan
import datetime as _dt
from functools import lru_cache
from fastapi import Header

log = logging.getLogger("jathagam")
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")

app = FastAPI(title="தமிழ் ஜாதகம் API", version=engine.CALC_VERSION,
              description="Deterministic Vedic chart calculations (traditional + KP) on Swiss Ephemeris.")

# CORS: only the origins listed in ALLOWED_ORIGINS (comma separated). Never "*" in production.
_origins = [o.strip() for o in os.environ.get("ALLOWED_ORIGINS", "http://localhost:5173,http://localhost:3000").split(",") if o.strip()]
app.add_middleware(CORSMiddleware, allow_origins=_origins, allow_methods=["GET", "POST"], allow_headers=["*", "x-admin-token"], allow_credentials=False)


class ChartRequest(BaseModel):
    name: str = Field(default="", max_length=80)
    gender: Optional[Literal["male", "female", "other"]] = None
    date: str = Field(..., pattern=r"^\d{4}-\d{2}-\d{2}$", description="yyyy-mm-dd (local civil date)")
    time: str = Field(..., pattern=r"^\d{2}:\d{2}(:\d{2})?$", description="24-hour hh:mm:ss local time")
    tz_id: str = Field(..., description="IANA zone, e.g. Asia/Kolkata")
    latitude: float = Field(..., ge=-90, le=90)
    longitude: float = Field(..., ge=-180, le=180)
    mode: Literal["traditional", "kp"] = "traditional"
    node: Literal["mean", "true"] = "mean"
    as_of: Optional[str] = Field(default=None, description="ISO datetime for 'current' dasha/transits; default = now at birthplace")

    @field_validator("tz_id")
    @classmethod
    def _tz(cls, v):
        try: ZoneInfo(v)
        except ZoneInfoNotFoundError: raise ValueError(f"unknown timezone id: {v}")
        return v


@app.get("/health")
def health():
    return {"ok": True, "engine": engine.ENGINE, "ephemeris": engine.EPHEMERIS_DATA, "version": engine.CALC_VERSION}


@app.get("/api/v1/places")
def api_places(q: str = Query(..., min_length=2, max_length=60), limit: int = Query(10, ge=1, le=25)):
    return {"results": places.search(q, limit)}


@app.get("/api/v1/timezone")
def api_timezone(latitude: float, longitude: float, date: str, time: str = "12:00:00", tz_id: Optional[str] = None):
    tz = tz_id or places.timezone_for(latitude, longitude)
    if not tz:
        raise HTTPException(422, "could not determine a timezone for these coordinates; supply tz_id")
    try:
        return places.offset_on(tz, date, time)
    except Exception as e:  # bad date / unknown zone
        raise HTTPException(422, str(e))


@app.post("/api/v1/chart")
def api_chart(req: ChartRequest):
    try:
        return engine.compute_chart(name=req.name, gender=req.gender, date=req.date, time=req.time, tz_id=req.tz_id,
                                    lat=req.latitude, lon=req.longitude, mode=req.mode, node=req.node, as_of=req.as_of)
    except ValueError as e:
        raise HTTPException(422, str(e))
    except Exception as e:
        log.exception("chart calculation failed")        # birth details are NOT logged
        raise HTTPException(500, "calculation failed: " + e.__class__.__name__)


# ---------------------------------------------------------------- தினசரி பஞ்சாங்கம் / ராசி பலன்
CHENNAI = palan.CHENNAI
_DATE_RE = r"^\d{4}-\d{2}-\d{2}$"


def _today_chennai() -> str:
    return _dt.datetime.now(ZoneInfo("Asia/Kolkata")).date().isoformat()


def _valid_date(d: str) -> str:
    try:
        _dt.date.fromisoformat(d)
    except ValueError:
        raise HTTPException(422, "date must be yyyy-mm-dd")
    return d


@lru_cache(maxsize=2048)   # cache key = date + location + zone (+ engine version via module constants)
def _panchang_cached(date: str, lat: float, lon: float, tz_id: str) -> dict:
    return panchang.compute_panchang(date=date, lat=lat, lon=lon, tz_id=tz_id)


@app.get("/api/v1/panchang")
def api_panchang(date: Optional[str] = None,
                 latitude: float = Query(CHENNAI["lat"], ge=-90, le=90),
                 longitude: float = Query(CHENNAI["lon"], ge=-180, le=180),
                 tz_id: str = CHENNAI["tz_id"], place: str = "சென்னை"):
    """Daily panchangam. Defaults to today's Chennai date and Chennai coordinates (Lahiri, Swiss Ephemeris)."""
    date = _valid_date(date or _today_chennai())
    try:
        ZoneInfo(tz_id)
    except ZoneInfoNotFoundError:
        raise HTTPException(422, f"unknown timezone id: {tz_id}")
    try:
        doc = dict(_panchang_cached(date, round(latitude, 4), round(longitude, 4), tz_id))
    except Exception as e:
        log.exception("panchang failed")
        raise HTTPException(500, "calculation failed: " + e.__class__.__name__)
    doc["place"] = dict(doc.get("place", {}), name_ta=place)
    doc["today_chennai"] = _today_chennai()
    return doc


@app.get("/api/v1/rasi-palan")
def api_rasi_palan(date: Optional[str] = None):
    """Public: approved ராசி பலன் set for the date (Chennai sunrise transits). 404 until an admin approves it."""
    date = _valid_date(date or _today_chennai())
    doc = palan.generate(date)
    if doc["status"] != "approved":
        raise HTTPException(404, "இந்த நாளுக்கான ராசி பலன் இன்னும் வெளியிடப்படவில்லை (not yet approved)")
    return doc


def _admin(token: Optional[str]):
    if not palan.check_token(token):
        raise HTTPException(401, "admin token missing or invalid")


@app.get("/api/v1/admin/rasi-palan")
def admin_preview(date: Optional[str] = None, x_admin_token: Optional[str] = Header(default=None)):
    """Admin preview (draft or approved) with every rule that fired, for astrologer review."""
    _admin(x_admin_token)
    return palan.generate(_valid_date(date or _today_chennai()))


class ApproveRequest(BaseModel):
    date: str = Field(..., pattern=_DATE_RE)
    approver: str = Field(default="admin", max_length=60)
    edits: Optional[dict] = Field(default=None, description="{rasi_index: {general_ta|work_ta|relationships_ta: text}}")


@app.post("/api/v1/admin/rasi-palan/approve")
def admin_approve(req: ApproveRequest, x_admin_token: Optional[str] = Header(default=None)):
    _admin(x_admin_token)
    return palan.approve(req.date, req.approver, req.edits)


@app.post("/api/v1/admin/rasi-palan/unpublish")
def admin_unpublish(req: ApproveRequest, x_admin_token: Optional[str] = Header(default=None)):
    _admin(x_admin_token)
    return palan.unpublish(req.date)
